{
  "group": "BarSeriesManager.run(Strategy,int,int) - additional scenarios",
  "cases": [
    {
      "input": [
        {
          "parameter": "strategy",
          "value": "validStrategyMock"
        },
        {
          "parameter": "startIndex",
          "value": "2"
        },
        {
          "parameter": "finishIndex",
          "value": "-1"
        }
      ],
      "expected": "IllegalArgumentException",
      "description": "Negative finishIndex should be rejected. The method must validate that both indexes are non‑negative and throw IllegalArgumentException before any processing."
    },
    {
      "input": [
        {
          "parameter": "strategy",
          "value": "validStrategyMock"
        },
        {
          "parameter": "startIndex",
          "value": "0"
        },
        {
          "parameter": "finishIndex",
          "value": "0"
        }
      ],
      "expected": "non‑null TradingRecord instance with zero trades (empty record)",
      "description": "Run on an empty BarSeries (size 0). With startIndex == finishIndex == 0 the manager should return an empty TradingRecord without throwing an exception."
    },
    {
      "input": [
        {
          "parameter": "strategy",
          "value": "validStrategyMock"
        },
        {
          "parameter": "startIndex",
          "value": "0"
        },
        {
          "parameter": "finishIndex",
          "value": "9"
        }
      ],
      "expected": "non‑null TradingRecord instance containing the trades generated by the strategy over the whole series",
      "description": "Boundary test where the range covers the entire BarSeries (size 10, indexes 0‑9). The method must process all bars and return a populated TradingRecord."
    },
    {
      "input": [
        {
          "parameter": "strategy",
          "value": "alwaysEnterExitStrategyMock"
        },
        {
          "parameter": "startIndex",
          "value": "5"
        },
        {
          "parameter": "finishIndex",
          "value": "6"
        }
      ],
      "expected": "non‑null TradingRecord instance with exactly one BUY trade (entry at index 5, exit at index 6)",
      "description": "Two‑bar window where the supplied strategy always signals an entry on the first bar and an exit on the next bar. The resulting TradingRecord should contain a single BUY trade."
    },
    {
      "input": [
        {
          "parameter": "strategy",
          "value": "neverEnterStrategyMock"
        },
        {
          "parameter": "startIndex",
          "value": "0"
        },
        {
          "parameter": "finishIndex",
          "value": "7"
        }
      ],
      "expected": "non‑null TradingRecord instance with zero trades (empty record)",
      "description": "Strategy that never returns a signal. Even though the index range is valid, no trades should be recorded."
    },
    {
      "input": [
        {
          "parameter": "strategy",
          "value": "singleBuyStrategyMock"
        },
        {
          "parameter": "startIndex",
          "value": "3"
        },
        {
          "parameter": "finishIndex",
          "value": "8"
        }
      ],
      "expected": "non‑null TradingRecord instance where all generated trades are of type BUY",
      "description": "Verify that the overload used by run(Strategy,int,int) defaults to TradeType.BUY. The mock strategy creates a few trades; each trade in the returned TradingRecord must have TradeType.BUY."
    }
  ]
}
